import Foundation
import SimCore
import XCTest

final class ConvexPrecisionTests: XCTestCase {
    func testThinObliqueCellAndTamperedCentroid() throws {
        // Saved failure: a valid 1.81e-10 m³ cell rejected by Float centroid integration.
        let bytes = Data(#"""
{"boundingRadius": 0.2477109730243683, "boundsMax": [0.008482118137180805, -1.862645149230957e-09, 3.346940502524376e-10], "boundsMin": [1.7462298274040222e-10, -0.49379047751426697, -0.03926728293299675], "centroid": [0.006360393948853016, -0.37000563740730286, -0.029143396764993668], "digest": "a451db2a8c0c4b7ff5d192fd70f685eef5ea11d8b2bc274545c7e5f566503016", "edges": [{"faceA": 0, "faceB": 1, "vertexA": 0, "vertexB": 1}, {"faceA": 1, "faceB": 2, "vertexA": 0, "vertexB": 2}, {"faceA": 0, "faceB": 2, "vertexA": 0, "vertexB": 3}, {"faceA": 1, "faceB": 3, "vertexA": 1, "vertexB": 2}, {"faceA": 0, "faceB": 3, "vertexA": 1, "vertexB": 3}, {"faceA": 2, "faceB": 3, "vertexA": 2, "vertexB": 3}], "stableID": "hull-a451db2a8c0c4b7f", "triangles": [[0, 1, 3], [0, 2, 1], [0, 3, 2], [1, 2, 3]], "vertices": [[1.7462298274040222e-10, -1.862645149230957e-09, 3.346940502524376e-10], [0.008478114381432533, -0.4926522970199585, -0.03834877535700798], [0.008481343276798725, -0.49357980489730835, -0.03895752876996994], [0.008482118137180805, -0.49379047751426697, -0.03926728293299675]], "volume": 1.8110583865915686e-10}
"""#.utf8)
        XCTAssertNoThrow(try JSONDecoder().decode(ConvexHullAsset.self, from: bytes))
        var changed = try XCTUnwrap(JSONSerialization.jsonObject(with: bytes) as? [String: Any])
        var centroid = try XCTUnwrap(changed["centroid"] as? [Double])
        centroid[0] += 0.01
        changed["centroid"] = centroid
        let tampered = try JSONSerialization.data(withJSONObject: changed)
        XCTAssertThrowsError(try JSONDecoder().decode(ConvexHullAsset.self, from: tampered)) { error in
            XCTAssertTrue(String(describing: error).contains("stored centroid"))
        }
    }
